import { THEME_MODES } from "@rapid7/rds-theme-metadata-provider";
import { getCallistoTheme } from "./getCallistoTheme";
export const DarkCallistoTheme = getCallistoTheme(THEME_MODES.DARK);
export const LightCallistoTheme = getCallistoTheme(THEME_MODES.LIGHT);
/**
 * Theme map for the Callisto RDS visual design, in both light & dark mode.
 */
export const CallistoThemeMap = {
    [THEME_MODES.DARK]: DarkCallistoTheme,
    [THEME_MODES.LIGHT]: LightCallistoTheme,
};
